// Semantic related-post finder.
//
// Primary: cosine similarity over precomputed embedding vectors
// (src/data/embeddings.json, generated by scripts/embed.py).
// Fallback: lightweight TF-IDF keyword similarity when no embeddings exist.

import embeddings from "../data/embeddings.json";

export interface PostLike {
  id: string;
  data: {
    title: string;
    description?: string;
    date: Date;
  };
}

type VecDb = Record<string, { hash?: string; model?: string; vector?: number[] }>;
const DB = embeddings as unknown as VecDb;

const STOPWORDS = new Set([
  "yang", "dan", "di", "ke", "dari", "untuk", "dengan", "pada", "adalah", "ini",
  "itu", "atau", "juga", "akan", "bisa", "dapat", "tidak", "dalam", "sebagai",
  "kita", "anda", "mereka", "saya", "kami", "agar", "oleh", "harus", "lebih",
  "the", "a", "an", "of", "to", "in", "for", "and", "or", "is", "are", "be",
  "with", "on", "by", "as", "at", "it", "this", "that", "from", "how", "what",
]);

function tokens(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\u00c0-\u024f\s-]/gi, " ")
    .split(/[\s-]+/)
    .filter((w) => w.length > 2 && !STOPWORDS.has(w) && !/^\d+$/.test(w));
}

export function tokenSet(p: PostLike): string[] {
  return tokens(`${p.data.title} ${p.data.description ?? ""}`.repeat(3));
}

function cosine(a: number[], b: number[]): number {
  const n = Math.min(a.length, b.length);
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < n; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return na && nb ? dot / (Math.sqrt(na) * Math.sqrt(nb)) : 0;
}

function vec(id: string): number[] | null {
  const v = DB[id]?.vector;
  return Array.isArray(v) && v.length ? v : null;
}

/** TF-IDF fallback ranking. */
function tfidfRelated(current: PostLike, all: PostLike[], n: number): PostLike[] {
  const docs = all.map((p) => ({ post: p, toks: tokenSet(p) }));
  const N = docs.length;
  if (N <= 1) return [];

  const df = new Map<string, number>();
  for (const d of docs) for (const t of new Set(d.toks)) df.set(t, (df.get(t) ?? 0) + 1);

  const idf = (t: string) => Math.log(1 + N / (df.get(t) ?? 1));
  const curToks = tokenSet(current);

  const scored = docs
    .filter((d) => d.post.id !== current.id)
    .map((d) => {
      const set = new Set(d.toks);
      let s = 0;
      for (const t of new Set(curToks)) if (set.has(t)) s += idf(t) * idf(t);
      return { post: d.post, score: s };
    })
    .filter((x) => x.score > 0);

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, n).map((x) => x.post);
}

/**
 * Return top-N most similar posts (excluding `current`).
 * Uses embeddings when available, otherwise falls back to TF-IDF.
 */
export function relatedPosts(current: PostLike, all: PostLike[], n = 3): PostLike[] {
  const cur = vec(current.id);
  if (!cur) return tfidfRelated(current, all, n);

  const scored = all
    .filter((p) => p.id !== current.id)
    .map((p) => {
      const v = vec(p.id);
      return { post: p, score: v ? cosine(cur, v) : -1 };
    })
    .filter((x) => x.score > 0.15); // buang yang tidak relevan sama sekali

  if (scored.length === 0) return tfidfRelated(current, all, n);

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, n).map((x) => x.post);
}